+'use strict';
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const db = require('../src/lib/db');
+const audit = require('../src/lib/audit');
+const { createInvoice } = require('../src/invoices/create');
+const { markPaid } = require('../src/invoices/pay');
+const { refundInvoice } = require('../src/invoices/refund');
+const { cancelInvoice } = require('../src/invoices/cancel');
+const { handle } = require('../src/http/routes');
+const { isSettled } = require('../src/modules/m17');
+const { exportPayments } = require('../src/export/payments');
+const { dailySummary } = require('../src/report/daily');
+
+test.beforeEach(() => { db.reset(); audit.clear(); });
+
+test('cancel preserves invoice data and records exactly one audit event across retries', () => {
+  createInvoice({ id: 'a', customer: 'c', amount: 500, items: [{ price: 250, qty: 2 }] });
+  const before = db.get('invoices', 'a');
+  assert.deepEqual(cancelInvoice('a'), { id: 'a', status: 'cancelled' });
+  assert.deepEqual(cancelInvoice('a'), { id: 'a', status: 'cancelled' });
+  assert.deepEqual(db.get('invoices', 'a'), { ...before, status: 'cancelled' });
+  assert.deepEqual(audit.entries(), [
+    { action: 'invoice.create', entityId: 'a' },
+    { action: 'invoice.cancel', entityId: 'a' },
+  ]);
+  assert.equal(isSettled(db.get('invoices', 'a')), false);
+});
+
+for (const status of ['paid', 'refunded']) {
+  test(`cancel rejects ${status} without writing state or audit`, () => {
+    createInvoice({ id: 'a', customer: 'c', amount: 500 });
+    markPaid('a');
+    if (status === 'refunded') refundInvoice('a');
+    const before = db.get('invoices', 'a');
+    const events = audit.entries();
+    assert.throws(() => cancelInvoice('a'), { code: 'INVOICE_CANCEL_CONFLICT' });
+    assert.equal(handle({ method: 'POST', path: '/invoices/a/cancel' }).status, 409);
+    assert.deepEqual(db.get('invoices', 'a'), before);
+    assert.deepEqual(audit.entries(), events);
+  });
+}
+
+test('missing invoice returns 404 without creating state or audit', () => {
+  assert.throws(() => cancelInvoice('missing'), { code: 'INVOICE_NOT_FOUND' });
+  assert.equal(handle({ method: 'POST', path: '/invoices/missing/cancel' }).status, 404);
+  assert.deepEqual(db.query('invoices'), []);
+  assert.deepEqual(audit.entries(), []);
+});
+
+test('HTTP create and cancel entry preserves response contract and rejects unrelated routes', () => {
+  assert.deepEqual(handle({ method: 'POST', path: '/invoices', body: { id: 'a', customer: 'c', amount: 500 } }), { status: 201 });
+  for (const req of [
+    { method: 'GET', path: '/invoices/a/cancel' },
+    { method: 'POST', path: '/invoices/a/cancel/extra' },
+  ]) assert.deepEqual(handle(req), { status: 404 });
+  assert.equal(db.get('invoices', 'a').status, 'open');
+  for (let i = 0; i < 2; i++) {
+    assert.deepEqual(handle({ method: 'POST', path: '/invoices/a/cancel' }), {
+      status: 200, body: { id: 'a', status: 'cancelled' },
+    });
+  }
+  assert.equal(audit.entries().filter((e) => e.action === 'invoice.cancel').length, 1);
+  assert.throws(() => refundInvoice('a'), /only paid/);
+});
+
+test('cancellation leaves payment CSV and daily summary unchanged', () => {
+  db.withTx((tx) => {
+    tx.insert('payments', { id: 2, paidAt: '2026-11-02T12:00:00Z', amount: 700 });
+    tx.insert('payments', { id: 1, paidAt: '2026-11-02T09:00:00Z', amount: 500 });
+  });
+  createInvoice({ id: 'a', customer: 'c', amount: 500 });
+  const csv = exportPayments();
+  const summary = dailySummary();
+  cancelInvoice('a');
+  assert.equal(exportPayments(), csv);
+  assert.deepEqual(dailySummary(), summary);
+  assert.deepEqual(summary, { count: 2, first: '2026-11-02T09:00:00Z', last: '2026-11-02T12:00:00Z' });
+});
*** End Patch"));
